// Base de datos completa oficial de Cobblemon (Total: 851 Pokémon)
export interface Move {
  nombre: string;
  nombre_en: string;
  tipo: string;
  categoria: 'Físico' | 'Especial' | 'Estado';
  potencia?: number;
  precision?: number;
  pp?: number;
  nivel?: number;
  metodo?: 'Nivel' | 'MT' | 'Huevo' | 'Tutor';
  razon?: string;
}

export interface MountData {
  is_mountable: boolean;
  category: 'aerial' | 'land' | 'water' | 'hybrid';
  category_es: 'Aérea' | 'Terrestre' | 'Acuática' | 'Híbrida (Tierra/Aire)';
  tier: 'S+' | 'S' | 'A' | 'B' | 'C';
  speed_score: number;
  acceleration: number;
  jump: number;
  stamina: number;
  seats: number;
  flight_style?: string;
  notes_es: string;
}

export interface PvpData {
  rol: string;
  objeto_recomendado: string;
  objeto_en: string;
  objeto_sprite?: string;
  naturaleza: string;
  evs: string;
  habilidad_recomendada: string;
  mejores_ataques: {
    nombre: string;
    nombre_en: string;
    tipo: string;
    categoria: 'Físico' | 'Especial' | 'Estado';
    razon: string;
  }[];
}

export interface Pokemon {
  id: number;
  name: string;
  name_es: string;
  types: string[];
  has_cobblemon_model?: boolean;
  cobblemon_model_url?: string;
  sprite: string;
  animated_sprite: string;
  artwork_fallback?: string;
  description_es: string;
  generation: number;
  abilities: {
    name: string;
    is_hidden: boolean;
    effect_es: string;
  }[];
  base_stats: {
    hp: number;
    attack: number;
    defense: number;
    sp_attack: number;
    sp_defense: number;
    speed: number;
    total: number;
  };
  spawns: {
    rareza: 'Común' | 'Poco común' | 'Raro' | 'Ultra Raro';
    niveles: string;
    condiciones_es: string;
    biomas_es: string[];
    biomas_tag: string[];
  };
  drops: {
    item_es: string;
    item_en: string;
    item_id?: string;
    sprite?: string;
    probabilidad: string;
    cantidad: string;
  }[];
  evolution_es: string;
  mount?: MountData;
  pvp: PvpData;
}

